// The loop. Audio in one end, a steer on the glass out the other.
//
//   AudioSource → Transcriber → SpeakerAttributor → TurnGate → Coach → Stage
//
// Every piece is already tested on its own; this is the wiring, and it owns
// exactly one thing of its own — the accumulated turn. PRODUCT.md is explicit
// that the gate must judge "the whole turn since the user last held the floor",
// not one Deepgram final, because judging a fragment is what caused the D-031
// misfires. Keeping that buffer here is the only reason this file has state.

import { openBestSource, type AudioSource, type Frame } from './capture'
import { Coach, isCoachError, type CoachTurn } from './coach'
import { SpeakerAttributor, type Who } from './speakers'
import { Transcriber, type DeepgramMessage } from './stt'
import { NUDGES, TurnGate, type GateConfig } from './turns'
import type { StateEvent, SteerEvent } from '../protocol'
import { PROTOCOL_VERSION } from '../protocol'
import type { Stage } from '../stage'

export type SessionSource = 'glasses' | 'phone' | 'browser'

export interface SessionOptions {
  stage: Stage
  deepgramKey: string
  source?: SessionSource
  mode?: string
  modeLabel?: string
  locale?: string
  gate?: GateConfig
  /** Told everything, so a debug panel can show why nothing fired. */
  onEvent?: (e: SessionEvent) => void
}

export type SessionEvent =
  | { type: 'listening'; sampleRate: number; source: SessionSource }
  | { type: 'transcript'; who: Who; text: string; isFinal: boolean }
  | { type: 'skipped'; reason: string; turn: string }
  | { type: 'asking'; turn: string }
  | { type: 'steer'; label: string; why: string; ms: number }
  | { type: 'dropped'; reason: string }
  | { type: 'error'; detail: string }
  | { type: 'stopped' }

export class Session {
  private source: AudioSource | null = null
  private transcriber: Transcriber | null = null
  private readonly attributor: SpeakerAttributor
  private readonly gate: TurnGate
  private readonly coach = new Coach()
  private running = false

  /** The other party's words since we last held the floor. */
  private theirTurn = ''
  /** Rolling context for the coach; far more than the twelve it will use. */
  private turns: CoachTurn[] = []
  private lastWho: Who | null = null

  constructor(private readonly opts: SessionOptions) {
    this.attributor = new SpeakerAttributor({
      // A laptop cannot tell two voices apart. Assuming "them" keeps the
      // coaching path exercised while testing and is wrong anywhere else.
      unknownPolicy: opts.source === 'browser' ? 'them' : 'them',
    })
    this.gate = new TurnGate(opts.gate ?? NUDGES)
  }

  get isRunning(): boolean {
    return this.running
  }

  async start(): Promise<void> {
    if (this.running) return
    this.running = true

    this.source = await openBestSource(this.opts.source ?? 'glasses')
    const kind = this.source.kind
    const sampleRate = this.source.sampleRate

    this.transcriber = new Transcriber(this.opts.deepgramKey, { sampleRate })
    this.transcriber.open({
      onOpen: () => {
        this.pushState('listening')
        this.emit({ type: 'listening', sampleRate, source: kind })
      },
      onMessage: (m) => this.onMessage(m),
      onError: (detail) => this.emit({ type: 'error', detail }),
      onClose: (code, reason) => {
        if (this.running) this.emit({ type: 'error', detail: `transcription closed (${code}) ${reason}`.trim() })
      },
    })

    await this.source.start((f: Frame) => this.onFrame(f))
  }

  async stop(): Promise<void> {
    if (!this.running) return
    this.running = false
    this.coach.cancel()
    await this.source?.stop()
    this.source = null
    this.transcriber?.close()
    this.transcriber = null
    this.attributor.reset()
    this.theirTurn = ''
    this.turns = []
    this.lastWho = null
    this.pushState('notListening')
    this.emit({ type: 'stopped' })
  }

  /** The ring's "what do I say?" — exempt from the debounce (PRODUCT.md). */
  async askNow(): Promise<void> {
    if (!this.running) return
    this.gate.markManualAsk(Date.now())
    await this.request(this.theirTurn || '(the user asked without a preceding turn)', true)
  }

  // MARK: - Plumbing

  private onFrame(f: Frame): void {
    this.attributor.noteFrame(f.role)
    this.transcriber?.send(f.pcm)
  }

  private onMessage(m: DeepgramMessage): void {
    if (m.kind !== 'transcript' || !m.text.trim()) return

    const index = m.words.find((w) => w.speaker !== null)?.speaker ?? null
    // Interims must not consume the frame window — only a final resolves it.
    const who = m.isFinal ? this.attributor.attribute(index) : (this.lastWho ?? 'them')
    this.emit({ type: 'transcript', who, text: m.text, isFinal: m.isFinal })

    if (!m.isFinal) return

    // Staleness: whatever lands while the coach is thinking may invalidate it.
    if (who === 'you') this.gate.noteUserSpeech(m.text)
    else this.gate.noteOtherSpeech(m.text)

    if (who === 'you') {
      // We took the floor, so their turn is over as far as the gate cares.
      this.theirTurn = ''
    } else {
      this.theirTurn = `${this.theirTurn} ${m.text}`.trim()
    }
    this.turns.push({ who, text: m.text })
    if (this.turns.length > 40) this.turns = this.turns.slice(-40)
    this.lastWho = who

    // Universal timing rule: never after the user's own turn.
    if (who !== 'them' || !m.speechFinal) return

    const decision = this.gate.evaluate(this.theirTurn, Date.now())
    if (!decision.fire) {
      this.emit({ type: 'skipped', reason: decision.reason, turn: this.theirTurn })
      return
    }
    void this.request(this.theirTurn, false)
  }

  private async request(turn: string, manual: boolean): Promise<void> {
    const startedAt = Date.now()
    if (!manual) this.gate.markFired(startedAt)
    this.emit({ type: 'asking', turn })

    const result = await this.coach.ask(this.turns, {
      mode: this.opts.mode ?? 'sales',
      locale: this.opts.locale ?? 'en',
      manual,
    })

    if (isCoachError(result)) {
      // A cancelled request is the newer turn winning, not a failure.
      if (result.kind !== 'aborted') {
        this.emit({ type: 'error', detail: result.kind === 'signed-out' ? 'Signed out' : `${result.status} ${result.detail}` })
      }
      return
    }

    // Manual asks are exempt from the staleness guard (PRODUCT.md).
    if (!manual) {
      const settled = this.gate.settle(Date.now())
      if (!settled.show) {
        this.emit({ type: 'dropped', reason: settled.reason })
        return
      }
    }

    const steer: SteerEvent = {
      v: PROTOCOL_VERSION,
      id: `${startedAt}`,
      content: result.suggestion,
      typeRaw: manual ? 'manual' : 'nudge',
      shortLabel: result.label,
      why: result.why,
      firedAt: new Date(startedAt).toISOString(),
    }
    this.opts.stage.onSteer(steer)
    this.emit({ type: 'steer', label: result.label, why: result.why, ms: Date.now() - startedAt })
  }

  /** The glass needs a session to exist before it will draw anything. */
  private pushState(engineState: StateEvent['engineState']): void {
    const now = new Date().toISOString()
    this.opts.stage.onState({
      v: PROTOCOL_VERSION,
      sessionId: 'glasses-local',
      engineState,
      isCalibrating: false,
      isWhispering: false,
      modeId: this.opts.mode ?? 'sales',
      modeLabel: this.opts.modeLabel ?? 'Sales',
      segmentStart: now,
      updatedAt: now,
    })
  }

  private emit(e: SessionEvent): void {
    this.opts.onEvent?.(e)
  }
}
