// When to speak. Ported line-for-line from `TurnHeuristics` in
// `Sources/TalkPilotCore/Intelligence/TranscriptionService.swift` and the
// end-of-turn stack documented in PRODUCT.md (D-026, D-031, D-025).
//
// This is a port, not a redesign. Every threshold and every word in these
// lexicons was paid for by a measured session on another platform; the
// glasses are the third client and must not quietly invent a fourth cadence.
// If a rule looks wrong, change it in PRODUCT.md and all three clients at
// once, never here alone.
//
// The layered signal, best first (PRODUCT.md "End-of-turn stack"):
//   1. Flux, a second Deepgram socket — semantic "they finished the thought"
//   2. `speech_final` + `looksLikeCompleteThought` — the fallback
//   3. the backchannel gate — never fire on "Yeah."
//   4. the staleness guard — drop what arrives too late to be true
// Steps 2-4 are here. Step 1 belongs to the transcription layer.

/** Words that read as mid-thought when a turn ends on them (EN + ES). */
const TRAILING_CONNECTORS = new Set([
  'and', 'but', 'so', 'or', 'because', 'then', 'like', 'um', 'uh', 'that', 'with', 'if',
  'y', 'pero', 'o', 'porque', 'entonces', 'este', 'eh', 'que', 'con', 'si',
])

/** Acknowledgments made while the *other* person still holds the floor. */
const BACKCHANNEL_WORDS = new Set([
  'yeah', 'yep', 'yup', 'ya', 'yes', 'ok', 'okay', 'k',
  // Hyphenated in transcripts ("mm-hm"); normalisation drops the hyphen, so
  // the lexicon stores the joined form.
  'mmhm', 'mmhmm', 'mhm', 'uhhuh', 'uhhu', 'mm', 'mmm', 'hmm', 'huh',
  'aha', 'ah', 'oh',
  'right', 'sure', 'exactly', 'totally', 'true', 'correct',
  'cool', 'nice', 'wow', 'gotcha', 'alright', 'absolutely', 'definitely',
  'sí', 'si', 'claro', 'exacto', 'exactamente', 'ajá', 'aja', 'ajam',
  'vale', 'órale', 'orale', 'totalmente', 'cierto', 'verdad', 'obvio',
  'guau', 'perfecto', 'listo', 'dale', 'ahá',
])

/** Noise that shouldn't decide anything on its own. */
const IGNORABLE_FILLERS = new Set([
  'um', 'uh', 'er', 'hm', 'like', 'well', 'and', 'but', 'so', 'just',
  'eh', 'este', 'pues', 'y', 'o', 'osea', 'bueno', 'nada',
  // Swift also lists "o_sea"; normalisation splits on the underscore, so it
  // can never match there either. Kept out rather than ported dead.
])

/**
 * Unicode-aware, matching Swift's `CharacterSet.alphanumerics.inverted`.
 * A plain `\w` split would strip the accents off "sí" and "ajá" and quietly
 * shrink the Spanish half of both lexicons.
 */
function normalizedWords(text: string): string[] {
  return text.toLowerCase().split(/[^\p{L}\p{N}]+/u).filter((w) => w.length > 0)
}

/**
 * A terminal period or question mark means the thought closed; a comma,
 * ellipsis, or trailing connector means it is still open.
 */
export function looksLikeCompleteThought(text: string): boolean {
  let trimmed = text.trim()
  if (!trimmed) return false

  // Ignore trailing quotes and brackets so `…done."` still counts as terminal.
  while (trimmed.length > 0 && `"'”’)]`.includes(trimmed[trimmed.length - 1]!)) {
    trimmed = trimmed.slice(0, -1)
  }
  if (!trimmed) return false

  if (trimmed.endsWith('...') || trimmed.endsWith('…')) return false

  const words = trimmed.split(' ')
  const lastWord = (words[words.length - 1] ?? '')
    .toLowerCase()
    .replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, '')
  if (TRAILING_CONNECTORS.has(lastWord)) return false

  const lastChar = trimmed[trimmed.length - 1]!
  return '.!?'.includes(lastChar) || '。！？'.includes(lastChar)
}

/**
 * True when the whole turn is pure acknowledgment. Pass the **accumulated
 * turn**, not one Deepgram final: judging a fragment is what caused the
 * misfires D-031 was written to stop. Length alone is not enough either —
 * "Not really, no." is three words and a real answer — so every content word
 * must also be an acknowledgment.
 */
export function isBackchannel(text: string, maxWords = 4): boolean {
  const words = normalizedWords(text).filter((w) => !IGNORABLE_FILLERS.has(w))
  // Nothing but fillers, or nothing at all, is not somebody's turn.
  if (words.length === 0) return true
  if (words.length > maxWords) return false
  return words.every((w) => BACKCHANNEL_WORDS.has(w))
}

// MARK: - The gate

export interface GateConfig {
  /** Minimum gap between auto fires. Nudges 15s, Teleprompter 4.5s. */
  debounceMs: number
  /** An answer older than this is no longer about the moment it was asked. */
  staleAfterMs: number
  /** Words the user may speak after firing before the answer is stale. */
  userWordBudget: number
}

/** PRODUCT.md: Nudges debounce 15s, staleness 5s, user budget 9 words. */
export const NUDGES: GateConfig = { debounceMs: 15_000, staleAfterMs: 5_000, userWordBudget: 9 }
/** PRODUCT.md: Teleprompter debounce 4.5s, staleness 5s, user budget 2 words. */
export const TELEPROMPTER: GateConfig = { debounceMs: 4_500, staleAfterMs: 5_000, userWordBudget: 2 }

export type SkipReason = 'backchannel' | 'incomplete' | 'debounce'
export type DropReason = 'other-spoke' | 'user-spoke' | 'too-late'

export type Decision =
  | { fire: true }
  | { fire: false; reason: SkipReason }

export type Settlement =
  | { show: true }
  | { show: false; reason: DropReason }

/**
 * One in-flight request at a time, which is all the glasses ever want: the
 * display holds a single card (WEARABLE_AR §8).
 *
 * Lifecycle: `evaluate` → if it fires, `markFired`, then report speech with
 * `noteOtherSpeech` / `noteUserSpeech` while the model thinks, then `settle`
 * when the answer arrives.
 */
export class TurnGate {
  private lastFiredAt = 0
  private pending: { firedAt: number; otherSpoke: boolean; userWords: number } | null = null

  constructor(private readonly cfg: GateConfig = NUDGES) {}

  /** `endedTurn` is the other party's accumulated turn since we last held the floor. */
  evaluate(endedTurn: string, now: number): Decision {
    if (isBackchannel(endedTurn)) return { fire: false, reason: 'backchannel' }
    if (!looksLikeCompleteThought(endedTurn)) return { fire: false, reason: 'incomplete' }
    if (this.lastFiredAt && now - this.lastFiredAt < this.cfg.debounceMs) {
      return { fire: false, reason: 'debounce' }
    }
    return { fire: true }
  }

  markFired(now: number): void {
    this.lastFiredAt = now
    this.pending = { firedAt: now, otherSpoke: false, userWords: 0 }
  }

  /** Substantive speech only — the caller filters backchannels out first. */
  noteOtherSpeech(text: string): void {
    if (!this.pending) return
    if (isBackchannel(text)) return
    if (normalizedWords(text).length === 0) return
    this.pending.otherSpoke = true
  }

  noteUserSpeech(text: string): void {
    if (!this.pending) return
    this.pending.userWords += normalizedWords(text).length
  }

  /**
   * The staleness guard (D-025/D-026/D-031). This guards the window *before*
   * display only. A card already on the glass keeps its dwell even if they
   * resume — yanking text mid-read costs more than it saves.
   */
  settle(now: number): Settlement {
    const p = this.pending
    this.pending = null
    if (!p) return { show: false, reason: 'too-late' }
    if (p.otherSpoke) return { show: false, reason: 'other-spoke' }
    if (p.userWords > this.cfg.userWordBudget) return { show: false, reason: 'user-spoke' }
    if (now - p.firedAt > this.cfg.staleAfterMs) return { show: false, reason: 'too-late' }
    return { show: true }
  }

  /** A manual ask is exempt from the debounce and from the staleness guard. */
  markManualAsk(now: number): void {
    this.lastFiredAt = now
    this.pending = null
  }
}
