// Who just spoke. The single hardest thing to get right, and the thing that
// poisons everything downstream when it is wrong: talk ratio, the end-of-turn
// stack, and the coach's read of the conversation (the same reasoning as the
// echo-suppression comment in `TranscriptionService.swift`).
//
// Two signals, in order of trust:
//
//   1. `speakerRole` from the Even bridge — Even's own array classifier, which
//      knows about bone conduction and direction of arrival. We do not have a
//      better one, and D-231 chose to trust it.
//   2. Deepgram diarization — a speaker index per word. It cannot know which
//      index is the wearer, only that two people are different.
//
// With neither (a laptop microphone), there is no honest answer.

import type { SpeakerRole } from './capture'

export type Who = 'you' | 'them'

/** What to assume when nothing knows. See `unknownPolicy` below. */
export type UnknownPolicy = 'them' | 'you'

export interface AttributorOptions {
  /**
   * A laptop microphone cannot tell two people apart, and the loop is
   * unusable without an answer. `them` keeps the coaching path exercised
   * while testing; it is wrong for production and only the browser source
   * should ever use it.
   */
  unknownPolicy?: UnknownPolicy
}

export class SpeakerAttributor {
  private readonly unknownPolicy: UnknownPolicy
  /** Roles observed on audio frames since the last transcript was attributed. */
  private seen: Partial<Record<SpeakerRole, number>> = {}
  /** The diarization index we have decided belongs to the wearer, if any. */
  private selfIndex: number | null = null

  constructor(opts: AttributorOptions = {}) {
    this.unknownPolicy = opts.unknownPolicy ?? 'them'
  }

  /** Called for every audio frame, before the words derived from it arrive. */
  noteFrame(role: SpeakerRole): void {
    this.seen[role] = (this.seen[role] ?? 0) + 1
  }

  /**
   * Learn which diarization index is the wearer, from a stretch the bridge
   * was confident about. Cheap to call; ignored when it disagrees with what
   * we already learned, since the bridge is the better signal.
   */
  private learnSelfIndex(index: number | null, role: SpeakerRole): void {
    if (index === null) return
    if (role === 'self' && this.selfIndex === null) this.selfIndex = index
  }

  /**
   * Attribute one finalized transcript and reset the frame window.
   * `speakerIndex` is Deepgram's, when diarization produced one.
   */
  attribute(speakerIndex: number | null = null): Who {
    const self = this.seen.self ?? 0
    const other = this.seen.other ?? 0
    this.seen = {}

    if (self > 0 || other > 0) {
      // The bridge spoke. Majority of the window wins; a tie goes to `them`,
      // because coaching on the other party is the whole product and a missed
      // steer costs more than an extra one.
      const role: SpeakerRole = self > other ? 'self' : 'other'
      this.learnSelfIndex(speakerIndex, role)
      return role === 'self' ? 'you' : 'them'
    }

    if (speakerIndex !== null && this.selfIndex !== null) {
      return speakerIndex === this.selfIndex ? 'you' : 'them'
    }

    return this.unknownPolicy
  }

  /** Forget everything. Call between sessions. */
  reset(): void {
    this.seen = {}
    this.selfIndex = null
  }
}
