// Vendor keys are fetched at runtime from the JWT-gated `get-api-keys` edge
// function, never compiled in — the same rule every other client follows
// (PRODUCT.md, "All vendor keys"). D-229 made that function validate the
// caller against a real user, so an anon key alone no longer opens it.

import { supabase } from '../channel'
import { SUPABASE_URL } from '../config'

export interface ApiKeys {
  deepgram: string
}

export type KeysError = { kind: 'signed-out' } | { kind: 'failed'; status: number; detail: string }

export async function fetchApiKeys(): Promise<ApiKeys | KeysError> {
  const { data: { session } } = await supabase.auth.getSession()
  if (!session) return { kind: 'signed-out' }

  const res = await fetch(`${SUPABASE_URL}/functions/v1/get-api-keys`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      authorization: `Bearer ${session.access_token}`,
    },
  })
  if (!res.ok) {
    return { kind: 'failed', status: res.status, detail: (await res.text().catch(() => '')).slice(0, 200) }
  }
  const body = await res.json() as { deepgram_key?: string }
  if (!body.deepgram_key) return { kind: 'failed', status: res.status, detail: 'No Deepgram key in the response' }
  return { deepgram: body.deepgram_key }
}

export function isKeysError(r: ApiKeys | KeysError): r is KeysError {
  return 'kind' in r
}
