// The client half of `supabase/functions/glasses-coach`. Deliberately thin:
// every decision about what to ask for, and how to phrase it, lives on the
// server so this is not a fourth copy of the prompt (see that function's
// header for why).

import { supabase } from '../channel'
import { SUPABASE_URL } from '../config'

export interface CoachTurn {
  who: 'you' | 'them'
  text: string
}

export interface CoachResult {
  label: string
  suggestion: string
  why: string
}

export type CoachError =
  | { kind: 'signed-out' }
  | { kind: 'aborted' }
  | { kind: 'failed'; status: number; detail: string }

export class Coach {
  private inFlight: AbortController | null = null

  /**
   * One request at a time. A second end-of-turn while the first is still
   * thinking means the first answer is already stale (D-025's guard would
   * drop it anyway), so cancelling is cheaper than racing.
   */
  async ask(
    turns: CoachTurn[],
    opts: { mode?: string; locale?: string; manual?: boolean } = {},
  ): Promise<CoachResult | CoachError> {
    this.inFlight?.abort()
    const controller = new AbortController()
    this.inFlight = controller

    const { data: { session } } = await supabase.auth.getSession()
    if (!session) return { kind: 'signed-out' }

    try {
      const res = await fetch(`${SUPABASE_URL}/functions/v1/glasses-coach`, {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          authorization: `Bearer ${session.access_token}`,
        },
        body: JSON.stringify({ turns, ...opts }),
        signal: controller.signal,
      })

      if (!res.ok) {
        const detail = await res.text().catch(() => '')
        return { kind: 'failed', status: res.status, detail: detail.slice(0, 200) }
      }
      return await res.json() as CoachResult
    } catch (err) {
      if ((err as Error).name === 'AbortError') return { kind: 'aborted' }
      return { kind: 'failed', status: 0, detail: (err as Error).message }
    } finally {
      if (this.inFlight === controller) this.inFlight = null
    }
  }

  cancel(): void {
    this.inFlight?.abort()
    this.inFlight = null
  }
}

export function isCoachError(r: CoachResult | CoachError): r is CoachError {
  return 'kind' in r
}
