import type { Locale } from '../i18n'
import { PROTOCOL_VERSION } from '../protocol'
import type { Stage } from '../stage'

// A scripted session: no microphone, no account, no network, no keys.
//
// Three audiences, one implementation:
//
//  - **Even's reviewers.** They install the build as a beta tester with no
//    TalkPilot account, and the core flow has to run "on glasses + ring input
//    alone" with the phone locked (App Submission & QA Guidelines,
//    "Locked-phone operation"). A sign-in wall fails that outright — the
//    reviewer cannot sign in, so without this there is nothing for them to test.
//  - **The simulator**, which has no microphone and no way through an OAuth
//    redirect, so it cannot reach a real session either.
//  - **Store screenshots**, which must "match what the app actually renders
//    on device" — these are that, rendered by the real Stage.
//
// The coaching copy mirrors the film's (`src/showcase/script.ts`): real
// product output, nothing invented for the demo. It is localized because it
// is user-facing text like any other (docs/PRODUCT.md §2b) — the film is
// English-only because its voices are, which does not apply here.

interface Localized {
  en: string
  es: string
}

type Beat =
  | { at: number; kind: 'steer'; label: Localized; why: Localized }
  | { at: number; kind: 'cue'; text: Localized }

/** One loop of the call, timed to roughly the film's pacing. */
const SCRIPT: Beat[] = [
  {
    at: 5_000,
    kind: 'steer',
    label: { en: 'Ask what changed', es: 'Pregunta qué cambió' },
    why: { en: 'They had budget. Something moved.', es: 'Tenían presupuesto. Algo cambió.' },
  },
  {
    at: 19_000,
    kind: 'steer',
    label: { en: 'Name the cost of waiting', es: 'Nombra el costo de esperar' },
    why: { en: 'A cut has a reason. Tie it to the problem.', es: 'Un recorte tiene motivo. Liga eso al problema.' },
  },
  {
    at: 33_000,
    kind: 'cue',
    text: { en: 'Slow down', es: 'Más despacio' },
  },
  {
    at: 43_000,
    kind: 'steer',
    label: { en: 'Close on a date', es: 'Cierra con una fecha' },
    why: { en: 'They just gave you a deadline.', es: 'Acaban de darte una fecha límite.' },
  },
]

const LOOP_MS = 60_000

/** What a ring tap answers with mid-demo, so the gesture has a visible response. */
const ON_DEMAND: { label: Localized; why: Localized } = {
  label: { en: 'Confirm the next step', es: 'Confirma el siguiente paso' },
  why: { en: 'Make the follow-up concrete.', es: 'Haz concreto el seguimiento.' },
}

export interface DemoOptions {
  stage: Stage
  locale: Locale
  /** Shown in the footer beside LIVE, so the glass never claims to be coaching a real call. */
  modeLabel: string
  onEvent?: (message: string) => void
}

export class DemoSession {
  private timers: ReturnType<typeof setTimeout>[] = []
  private running = false
  private seq = 0

  constructor(private readonly opts: DemoOptions) {}

  start(): void {
    if (this.running) return
    this.running = true
    this.pushState('listening')
    this.opts.onEvent?.('Demo started — scripted call, no microphone.')
    this.loop()
  }

  stop(): void {
    if (!this.running) return
    this.running = false
    this.clear()
    this.pushState('notListening')
    this.opts.onEvent?.('Demo stopped.')
  }

  /** The manual ask, exempt from the script's timing — same as a real session. */
  askNow(): void {
    if (!this.running) return
    this.steer(ON_DEMAND.label, ON_DEMAND.why)
    this.opts.onEvent?.('Demo: suggestion on request.')
  }

  private loop(): void {
    for (const beat of SCRIPT) {
      this.timers.push(
        setTimeout(() => {
          if (!this.running) return
          if (beat.kind === 'steer') this.steer(beat.label, beat.why)
          else this.cue(beat.text)
        }, beat.at),
      )
    }
    // Loop rather than fall silent: a reviewer who leaves it running has to
    // still find it alive ("After 2 minutes idle the app is still alive and
    // responsive"), and screenshots can be taken at any point.
    this.timers.push(
      setTimeout(() => {
        if (!this.running) return
        this.clear()
        this.loop()
      }, LOOP_MS),
    )
  }

  private steer(label: Localized, why: Localized): void {
    this.opts.stage.onSteer({
      v: PROTOCOL_VERSION,
      id: `demo-${this.seq++}`,
      content: this.pick(label),
      typeRaw: 'nudge',
      shortLabel: this.pick(label),
      why: this.pick(why),
      firedAt: new Date().toISOString(),
    })
  }

  private cue(text: Localized): void {
    this.opts.stage.onCue({
      v: PROTOCOL_VERSION,
      id: `demo-cue-${this.seq++}`,
      text: this.pick(text),
      kindRaw: 'pace',
      firedAt: new Date().toISOString(),
    })
  }

  private pick(l: Localized): string {
    return this.opts.locale === 'es' ? l.es : l.en
  }

  private pushState(engineState: 'listening' | 'notListening'): void {
    this.opts.stage.onState({
      v: PROTOCOL_VERSION,
      engineState,
      isCalibrating: false,
      isWhispering: false,
      modeId: 'demo',
      modeLabel: this.opts.modeLabel,
      updatedAt: new Date().toISOString(),
    })
  }

  private clear(): void {
    for (const t of this.timers) clearTimeout(t)
    this.timers = []
  }
}
