// Where the sound comes from. One interface, three implementations, because
// the same coaching loop has to run in three places:
//
//   glasses — the G2's own array, over the Even bridge. What ships.
//   phone   — the same bridge, the phone's mic. Useful when the glasses are
//             flat, and the honest comparison for the §3a.1 question.
//   browser — getUserMedia. What makes the whole loop testable on a laptop,
//             and what the EvenHub simulator feeds when it runs the app.
//
// Everything downstream takes `Frame` and does not know or care which one is
// running. Switching is one enum, which is the point: the hardware question
// (can four mics on a frame hear the other person?) stays isolated from every
// other question in the build.

import {
  AudioInputSource,
  AudioSpeakerRole,
  waitForEvenAppBridge,
  type EvenAppBridge,
} from '@evenrealities/even_hub_sdk'

/** Who the host thinks is talking. Even's own classifier, not ours (D-231). */
export type SpeakerRole = 'self' | 'other' | 'unknown'

export interface Frame {
  /** Signed 16-bit little-endian mono, the format both the SDK and Deepgram want. */
  pcm: Uint8Array
  role: SpeakerRole
  /** Glasses only; null from the phone mic, the browser, and older hosts. */
  direction: number | null
  at: number
}

export interface AudioSource {
  readonly kind: 'glasses' | 'phone' | 'browser'
  /** Hz. Reported rather than resampled — Deepgram takes it as a parameter. */
  readonly sampleRate: number
  start(onFrame: (f: Frame) => void): Promise<void>
  stop(): Promise<void>
}

/**
 * The simulator documents 16000 Hz, and the SDK gives no way to ask. If real
 * firmware disagrees the probe will say so and this constant is the one place
 * to change.
 */
export const BRIDGE_SAMPLE_RATE = 16_000

function toUint8(raw: unknown): Uint8Array {
  if (raw instanceof Uint8Array) return raw
  if (Array.isArray(raw)) return new Uint8Array(raw)
  // Some hosts JSON-encode the Uint8List as base64.
  if (typeof raw === 'string') {
    const bin = atob(raw)
    const out = new Uint8Array(bin.length)
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
    return out
  }
  return new Uint8Array(0)
}

function toRole(raw: unknown): SpeakerRole {
  return raw === AudioSpeakerRole.Self ? 'self' : raw === AudioSpeakerRole.Other ? 'other' : 'unknown'
}

/** True only inside the Even app's WebView. The SDK's own runtime requirement. */
export function hasEvenBridge(): boolean {
  return typeof window !== 'undefined'
    && typeof (window as { flutter_inappwebview?: { callHandler?: unknown } }).flutter_inappwebview?.callHandler === 'function'
}

export class BridgeAudioSource implements AudioSource {
  readonly sampleRate = BRIDGE_SAMPLE_RATE
  private unsubscribe: (() => void) | null = null

  constructor(readonly kind: 'glasses' | 'phone', private readonly bridge: EvenAppBridge) {}

  static async connect(kind: 'glasses' | 'phone', timeoutMs = 2_500): Promise<BridgeAudioSource | null> {
    if (!hasEvenBridge()) return null
    try {
      const bridge = await Promise.race([
        waitForEvenAppBridge(),
        new Promise<null>((r) => setTimeout(() => r(null), timeoutMs)),
      ])
      return bridge ? new BridgeAudioSource(kind, bridge) : null
    } catch {
      return null
    }
  }

  async start(onFrame: (f: Frame) => void): Promise<void> {
    this.unsubscribe = this.bridge.onEvenHubEvent((event) => {
      const audio = event.audioEvent
      if (!audio) return
      onFrame({
        pcm: toUint8(audio.audioPcm),
        role: toRole(audio.speakerRole),
        direction: audio.direction ?? null,
        at: Date.now(),
      })
    })
    // The SDK requires the startup page to exist before the glasses mic opens;
    // the caller owns that page, so it is their job to have created it first.
    const ok = await this.bridge.audioControl(
      true,
      this.kind === 'glasses' ? AudioInputSource.Glasses : AudioInputSource.Phone,
    )
    if (ok === false) {
      await this.stop()
      throw new Error(`audioControl refused for the ${this.kind} microphone`)
    }
  }

  async stop(): Promise<void> {
    this.unsubscribe?.()
    this.unsubscribe = null
    await this.bridge.audioControl(false).catch(() => undefined)
  }
}

export class BrowserAudioSource implements AudioSource {
  readonly kind = 'browser'
  private ctx: AudioContext | null = null
  private stream: MediaStream | null = null
  private node: ScriptProcessorNode | null = null
  private rate = 48_000

  get sampleRate(): number {
    return this.rate
  }

  async start(onFrame: (f: Frame) => void): Promise<void> {
    this.stream = await navigator.mediaDevices.getUserMedia({
      // The room is the signal. Browser cleanup is tuned for a call, where
      // suppressing everything but the near voice is the goal — the opposite
      // of what coaching needs (D-125).
      audio: { channelCount: 1, echoCancellation: false, noiseSuppression: false, autoGainControl: false },
    })
    this.ctx = new AudioContext()
    this.rate = this.ctx.sampleRate
    const src = this.ctx.createMediaStreamSource(this.stream)
    // Deprecated, and still the only one-file way to get raw samples. An
    // AudioWorklet needs a separate module served at its own URL, which the
    // packaged .ehpk makes awkward for no gain at this size.
    this.node = this.ctx.createScriptProcessor(4096, 1, 1)
    this.node.onaudioprocess = (ev) => {
      const input = ev.inputBuffer.getChannelData(0)
      const out = new Int16Array(input.length)
      for (let i = 0; i < input.length; i++) {
        const s = Math.max(-1, Math.min(1, input[i]!))
        out[i] = s < 0 ? s * 0x8000 : s * 0x7fff
      }
      onFrame({
        pcm: new Uint8Array(out.buffer.slice(0)),
        // A laptop mic has no idea who is talking; the gate treats unknown as
        // "could be either", which is the safe reading.
        role: 'unknown',
        direction: null,
        at: Date.now(),
      })
    }
    src.connect(this.node)
    // Chrome will not run a ScriptProcessor that reaches no destination.
    // A zero gain keeps it alive without echoing the room back at the room.
    const mute = this.ctx.createGain()
    mute.gain.value = 0
    this.node.connect(mute)
    mute.connect(this.ctx.destination)
  }

  async stop(): Promise<void> {
    if (this.node) this.node.onaudioprocess = null
    this.node?.disconnect()
    this.node = null
    this.stream?.getTracks().forEach((t) => t.stop())
    this.stream = null
    await this.ctx?.close().catch(() => undefined)
    this.ctx = null
  }
}

/** Prefer the glasses, fall back to the browser. The order the product wants. */
export async function openBestSource(preferred: 'glasses' | 'phone' | 'browser' = 'glasses'): Promise<AudioSource> {
  if (preferred !== 'browser') {
    const bridge = await BridgeAudioSource.connect(preferred)
    if (bridge) return bridge
  }
  return new BrowserAudioSource()
}
