// Speech to text, matching iOS exactly.
//
// `TranscriptionService.setMode(.diarized)` forces `forceV1Endpoint = true`,
// so the phone's single-microphone path is **nova-3 on v1**, not Flux — the
// v2 branch in `buildDeepgramURL` is unreachable in that mode today. iOS then
// runs `FluxTurnDetector` as a *second* socket whose only job is the semantic
// end-of-turn (`type: "TurnInfo"`, `event: "EndOfTurn"`).
//
// The glasses start with the first socket only, and take end-of-turn from
// `speech_final` plus the heuristics in `turns.ts`. That is not a shortcut
// invented here: PRODUCT.md names it as layer 2 of the end-of-turn stack, the
// documented fallback "whenever Flux is unhealthy". Adding the Flux sidecar
// later is additive and changes nothing below.
//
// Known gap, deliberately carried: the Deepgram key reaches the browser and a
// curious user can read it out of devtools. iOS fetches the same key from
// `get-api-keys` and connects directly too, so this is the established
// posture rather than a new hole — but a compiled binary hides it better than
// a web page does. The fix is Deepgram's short-lived scoped tokens, which
// wants its own change.

const V1_ENDPOINT = 'wss://api.deepgram.com/v1/listen'

export interface DeepgramOptions {
  /** Whatever the source reports. The bridge gives 16000; a laptop gives 48000. */
  sampleRate: number
  /** "multi" matches iOS, and is what makes the es-419 half work. */
  language?: string
}

/**
 * Query exactly as `buildDeepgramURL`'s `.diarized where forceV1Endpoint`
 * case builds it. `endpointing=500` is the one that matters: 500 ms of
 * silence turns into `speech_final`, which is our end-of-turn trigger.
 */
export function buildDeepgramUrl({ sampleRate, language = 'multi' }: DeepgramOptions): string {
  const q = new URLSearchParams({
    model: 'nova-3',
    diarize: 'true',
    smart_format: 'true',
    interim_results: 'true',
    endpointing: '500',
    utterance_end_ms: '3000',
    vad_events: 'true',
    filler_words: 'false',
    encoding: 'linear16',
    sample_rate: String(sampleRate),
    channels: '1',
    language,
  })
  return `${V1_ENDPOINT}?${q.toString()}`
}

export interface Word {
  word: string
  speaker: number | null
  start: number
  end: number
}

export type DeepgramMessage =
  | { kind: 'transcript'; text: string; isFinal: boolean; speechFinal: boolean; words: Word[] }
  | { kind: 'utterance-end' }
  | { kind: 'speech-started' }
  | { kind: 'other'; type: string | null }

/**
 * Shapes taken from `DeepgramResponse` in `TranscriptionService.swift`, which
 * is what the two clients already agree on. Anything unrecognised degrades to
 * `other` rather than throwing: a socket that dies on an unexpected key is a
 * worse failure than one that ignores it.
 */
export function parseDeepgramMessage(raw: string): DeepgramMessage {
  let json: Record<string, unknown>
  try {
    json = JSON.parse(raw) as Record<string, unknown>
  } catch {
    return { kind: 'other', type: null }
  }

  const type = typeof json.type === 'string' ? json.type : null
  if (type === 'UtteranceEnd') return { kind: 'utterance-end' }
  if (type === 'SpeechStarted') return { kind: 'speech-started' }

  const channel = json.channel as { alternatives?: Array<{ transcript?: string; words?: unknown[] }> } | undefined
  const alt = channel?.alternatives?.[0]
  if (!alt || typeof alt.transcript !== 'string') return { kind: 'other', type }

  const words: Word[] = Array.isArray(alt.words)
    ? (alt.words as Array<Record<string, unknown>>).map((w) => ({
        word: typeof w.word === 'string' ? w.word : '',
        speaker: typeof w.speaker === 'number' ? w.speaker : null,
        start: typeof w.start === 'number' ? w.start : 0,
        end: typeof w.end === 'number' ? w.end : 0,
      }))
    : []

  return {
    kind: 'transcript',
    text: alt.transcript,
    isFinal: json.is_final === true,
    speechFinal: json.speech_final === true,
    words,
  }
}

export interface TranscriberHandlers {
  onMessage: (m: DeepgramMessage) => void
  onOpen?: () => void
  onClose?: (code: number, reason: string) => void
  onError?: (detail: string) => void
}

/**
 * The socket. Audio in, messages out; every decision about what the words
 * *mean* belongs to the caller.
 */
export class Transcriber {
  private ws: WebSocket | null = null
  private keepAlive: ReturnType<typeof setInterval> | null = null

  constructor(private readonly apiKey: string, private readonly opts: DeepgramOptions) {}

  get isOpen(): boolean {
    return this.ws?.readyState === WebSocket.OPEN
  }

  open(h: TranscriberHandlers): void {
    // A browser cannot set headers on a WebSocket, so Deepgram takes the key
    // as a subprotocol instead. Same key, same account, different envelope.
    const ws = new WebSocket(buildDeepgramUrl(this.opts), ['token', this.apiKey])
    ws.binaryType = 'arraybuffer'
    this.ws = ws

    ws.onopen = () => {
      // Deepgram closes an idle socket after ~10s. A conversation has pauses
      // longer than that; the KeepAlive frame is how you survive them.
      this.keepAlive = setInterval(() => {
        if (ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify({ type: 'KeepAlive' }))
      }, 8_000)
      h.onOpen?.()
    }
    ws.onmessage = (ev) => {
      if (typeof ev.data === 'string') h.onMessage(parseDeepgramMessage(ev.data))
    }
    ws.onerror = () => h.onError?.('Deepgram socket error')
    ws.onclose = (ev) => {
      this.clearKeepAlive()
      h.onClose?.(ev.code, ev.reason)
    }
  }

  send(pcm: Uint8Array): void {
    if (this.ws?.readyState !== WebSocket.OPEN) return
    this.ws.send(pcm)
  }

  /** Ask Deepgram to flush and close cleanly, so the last words are not lost. */
  close(): void {
    this.clearKeepAlive()
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ type: 'CloseStream' }))
    }
    this.ws?.close()
    this.ws = null
  }

  private clearKeepAlive(): void {
    if (this.keepAlive) clearInterval(this.keepAlive)
    this.keepAlive = null
  }
}
