// The standalone glasses app: the G2 hears the room, we coach, the glass shows
// it. No phone session, no companion channel — this is the architecture D-231
// chose, and the one EvenHub review requires (the core flow must run on
// glasses and ring alone, with the phone locked).
//
// Everything hard lives in `src/engine/`, tested on its own. This file is the
// screen: a gate, a start button, the glass, and a log honest enough to show
// why nothing fired.

import { supabase } from '../channel'
import { fetchApiKeys, isKeysError } from '../engine/keys'
import { hasEvenBridge } from '../engine/capture'
import { Session, type SessionEvent, type SessionSource } from '../engine/session'
import { DemoSession } from './demo'
import { GlassesRenderer, type GlassesInput } from '../glasses'
import { resolveLocale, strings } from '../i18n'
import { Stage, sameFrame, type Frame } from '../stage'

const t = strings(resolveLocale())
const stage = new Stage({ live: t.live, paused: t.paused, calibrating: t.calibrating, listening: t.listening, noSession: t.glassesIdle })

const root = document.getElementById('stage')!
root.className = 'film live coach'
root.innerHTML = `
  <div class="scene" aria-hidden="true">
    <div class="photo-fallback"></div>
    <div class="grade"></div>
    <div class="lens"></div>
    <div class="frame"></div>
    <div class="hud">
      <div class="hud-boot">TalkPilot</div>
      <div class="hud-steer" hidden>
        <img class="hud-brand" src="${import.meta.env.BASE_URL}brand/talkpilot.png" alt="" />
        <div class="hud-label"></div>
        <div class="hud-why"></div>
      </div>
      <div class="hud-cue" hidden><img class="hud-brand" src="${import.meta.env.BASE_URL}brand/talkpilot.png" alt="" /><span class="hud-cue-text"></span></div>
      <div class="hud-status"></div>
    </div>
  </div>

  <section class="overlay gate">
    <p class="eyebrow">TalkPilot on your glasses</p>
    <h1>Sign in to start<br />listening.</h1>
    <p class="hint in-app" id="in-app-hint" hidden>${t.inAppHint}</p>
    <div class="providers" id="providers">
      <button class="provider" type="button" data-provider="google">${t.continueWith} Google</button>
      <button class="provider" type="button" data-provider="apple">${t.continueWith} Apple</button>
      <button class="provider" type="button" data-provider="azure">${t.continueWith} Microsoft</button>
      <button class="link-btn" type="button" id="use-email">${t.useEmail}</button>
    </div>
    <form class="signin" id="signin" hidden>
      <input name="email" type="email" autocomplete="username" placeholder="${t.email}" required />
      <input name="password" type="password" autocomplete="current-password" placeholder="${t.password}" />
      <button class="cta" type="submit">${t.signIn}</button>
      <button class="link-btn" type="button" id="send-code">${t.sendCode}</button>
    </form>
    <form class="signin" id="code" hidden>
      <p class="hint" id="code-hint"></p>
      <input name="token" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" placeholder="${t.codePlaceholder}" required />
      <button class="cta" type="submit">${t.verify}</button>
    </form>
    <p class="error" id="gate-error" hidden></p>
    <button class="link-btn" type="button" id="demo">${t.demoStart}</button>
  </section>

  <div class="deck" hidden id="deck">
    <div class="deck-row">
      <span class="who" id="who"></span>
      <div class="sources" id="sources"></div>
      <button class="btn primary" id="listen">Start listening</button>
      <button class="btn" id="ask" disabled>Ask now</button>
      <button class="link-btn" id="demo-deck">${t.demoStart}</button>
      <button class="link-btn" id="signout">${t.signOut}</button>
    </div>
    <p class="deck-status" id="deck-status">Ready.</p>
    <pre class="log" id="log"></pre>
  </div>
`

const $ = <T extends HTMLElement>(sel: string): T => root.querySelector<T>(sel)!
const gate = $('.gate')
const deck = $('#deck')
const gateError = $('#gate-error')
const deckStatus = $('#deck-status')
const logEl = $<HTMLPreElement>('#log')
const listenBtn = $<HTMLButtonElement>('#listen')
const askBtn = $<HTMLButtonElement>('#ask')
const demoBtns = [$<HTMLButtonElement>('#demo'), $<HTMLButtonElement>('#demo-deck')]
const steerEl = $('.hud-steer')
const labelEl = $('.hud-label')
const whyEl = $('.hud-why')
const cueEl = $('.hud-cue')
const cueText = $('.hud-cue-text')
const statusEl = $('.hud-status')

let session: Session | null = null
let demo: DemoSession | null = null
let signedIn = false
let glasses: GlassesRenderer | null = null
let source: SessionSource = hasEvenBridge() ? 'glasses' : 'browser'
let lastFrame: Frame | null = null

function log(line: string): void {
  const t = new Date().toISOString().slice(11, 19)
  logEl.textContent = `${t}  ${line}\n${logEl.textContent}`.slice(0, 6000)
}

// MARK: - The glass

function show(el: HTMLElement, on: boolean): void {
  if (on) {
    el.hidden = false
    el.classList.remove('show')
    void el.offsetWidth
    el.classList.add('show')
  } else {
    el.classList.remove('show')
  }
}

function render(frame: Frame): void {
  statusEl.textContent = frame.footer
  if (frame.kind === 'steer') {
    labelEl.textContent = frame.primary
    whyEl.textContent = frame.secondary
    show(steerEl, true)
    show(cueEl, false)
  } else if (frame.kind === 'cue') {
    cueText.textContent = frame.primary
    show(cueEl, true)
    show(steerEl, false)
  } else {
    show(steerEl, false)
    show(cueEl, false)
  }
}

setInterval(() => {
  const frame = stage.frame()
  if (sameFrame(lastFrame, frame)) return
  lastFrame = frame
  render(frame)
  void glasses?.render(frame, { listening: !!session || !!demo })
}, 250)

// MARK: - Session

function onSessionEvent(e: SessionEvent): void {
  switch (e.type) {
    case 'listening':
      deckStatus.textContent = `Listening on the ${e.source} microphone at ${e.sampleRate} Hz.`
      log(`listening — ${e.source} @ ${e.sampleRate} Hz`)
      break
    case 'transcript':
      if (e.isFinal) log(`${e.who === 'you' ? 'YOU ' : 'THEM'}  ${e.text}`)
      break
    case 'skipped':
      log(`skipped (${e.reason})`)
      break
    case 'asking':
      log('asking the coach…')
      break
    case 'steer':
      log(`STEER  ${e.label}${e.why ? ` — ${e.why}` : ''}  [${e.ms} ms]`)
      deckStatus.textContent = `Last steer took ${(e.ms / 1000).toFixed(1)} s.`
      break
    case 'dropped':
      log(`dropped (${e.reason}) — the moment had passed`)
      break
    case 'error':
      log(`error: ${e.detail}`)
      deckStatus.textContent = e.detail
      break
    case 'stopped':
      log('stopped')
      break
  }
}

async function startListening(): Promise<void> {
  stopDemo()
  listenBtn.disabled = true
  deckStatus.textContent = 'Fetching keys…'
  const keys = await fetchApiKeys()
  if (isKeysError(keys)) {
    deckStatus.textContent = keys.kind === 'signed-out' ? 'Signed out.' : `Could not fetch keys: ${keys.status} ${keys.detail}`
    log(deckStatus.textContent)
    listenBtn.disabled = false
    return
  }

  session = new Session({
    stage,
    deepgramKey: keys.deepgram,
    source,
    mode: 'sales',
    modeLabel: 'Sales',
    locale: resolveLocale(),
    onEvent: onSessionEvent,
  })

  try {
    await session.start()
    root.classList.add('on')
    listenBtn.textContent = 'Stop'
    listenBtn.classList.remove('primary')
    askBtn.disabled = false
  } catch (err) {
    deckStatus.textContent = `Could not start: ${(err as Error).message}`
    log(deckStatus.textContent)
    session = null
  } finally {
    listenBtn.disabled = false
  }
}

function startDemo(): void {
  if (demo) return
  demo = new DemoSession({
    stage,
    locale: resolveLocale(),
    modeLabel: t.demoMode,
    onEvent: (m) => {
      log(m)
      deckStatus.textContent = m
    },
  })
  demo.start()
  root.classList.add('on')
  gate.hidden = true
  for (const b of demoBtns) b.textContent = t.demoStop
  askBtn.disabled = false
}

function stopDemo(): void {
  if (!demo) return
  demo.stop()
  demo = null
  root.classList.remove('on')
  // Signed out, the gate is what should be showing again.
  if (!signedIn) gate.hidden = false
  for (const b of demoBtns) b.textContent = t.demoStart
  askBtn.disabled = true
}

function toggleDemo(): void {
  if (demo) stopDemo()
  else startDemo()
}

async function stopListening(): Promise<void> {
  await session?.stop()
  session = null
  root.classList.remove('on')
  listenBtn.textContent = 'Start listening'
  listenBtn.classList.add('primary')
  askBtn.disabled = true
}

listenBtn.addEventListener('click', () => void (session ? stopListening() : startListening()))
askBtn.addEventListener('click', () => void session?.askNow())

// MARK: - Source picker

const sourcesEl = $('#sources')
const available: SessionSource[] = hasEvenBridge() ? ['glasses', 'phone', 'browser'] : ['browser']
sourcesEl.innerHTML = available
  .map((s) => `<button class="btn src" type="button" data-src="${s}" aria-pressed="${s === source}">${s}</button>`)
  .join('')
sourcesEl.addEventListener('click', (ev) => {
  const b = (ev.target as HTMLElement).closest<HTMLButtonElement>('.src')
  if (!b || session) return
  source = b.dataset.src as SessionSource
  for (const el of sourcesEl.querySelectorAll<HTMLButtonElement>('.src')) {
    el.setAttribute('aria-pressed', String(el.dataset.src === source))
  }
})

// MARK: - Ring

function onInput(input: GlassesInput): void {
  if (input === 'tap' || input === 'menuAsk') {
    if (demo) demo.askNow()
    else void session?.askNow()
  } else if (input === 'menuDemo') {
    toggleDemo()
  } else if (input === 'hold' || input === 'menuStart' || input === 'menuStop') {
    if (demo) stopDemo()
    else void (session ? stopListening() : startListening())
  }
}

// MARK: - Gate

const providers = $('#providers')
const form = $<HTMLFormElement>('#signin')
const codeForm = $<HTMLFormElement>('#code')
const codeHint = $('#code-hint')
let codeEmail = ''

/** This page's own URL, cleaned of any auth leftovers, for OAuth to return to. */
function returnUrl(): string {
  const u = new URL(location.href)
  u.hash = ''
  for (const k of ['code', 'error', 'error_code', 'error_description', 'access_token', 'refresh_token', 'token_type', 'type']) u.searchParams.delete(k)
  return u.toString()
}

/**
 * Google, Apple and Microsoft work in a browser and cannot work inside the
 * Even app's WebView — Google refuses WebViews outright, and a browser
 * redirect has nowhere to return to. So the bridge decides which half of this
 * gate exists, and on a laptop every account type can sign in.
 */
providers.addEventListener('click', async (ev) => {
  const b = (ev.target as HTMLElement).closest<HTMLButtonElement>('.provider')
  if (!b) return
  const provider = b.dataset.provider as 'google' | 'apple' | 'azure'
  gateError.hidden = true
  b.disabled = true
  const { error } = await supabase.auth.signInWithOAuth({
    provider,
    options: { redirectTo: returnUrl(), ...(provider === 'azure' ? { scopes: 'email openid profile' } : {}) },
  })
  if (error) {
    b.disabled = false
    fail(`${t.signInFailed} ${error.message}`)
  }
})

$<HTMLButtonElement>('#use-email').addEventListener('click', () => {
  providers.hidden = true
  form.hidden = false
})

function fail(msg: string): void {
  gateError.textContent = msg
  gateError.hidden = false
}

form.addEventListener('submit', async (ev) => {
  ev.preventDefault()
  const data = new FormData(form)
  const password = String(data.get('password') ?? '')
  if (!password) return fail('Enter a password, or use the one-time code.')
  gateError.hidden = true
  const { error } = await supabase.auth.signInWithPassword({
    email: String(data.get('email') ?? '').trim(),
    password,
  })
  if (error) fail(/invalid login/i.test(error.message) ? t.wrongPassword : error.message)
})

$<HTMLButtonElement>('#send-code').addEventListener('click', async () => {
  const email = String(new FormData(form).get('email') ?? '').trim()
  if (!email) return fail('Enter your email first.')
  gateError.hidden = true
  const { error } = await supabase.auth.signInWithOtp({ email, options: { shouldCreateUser: false } })
  if (error) return fail(`${t.codeFailed} ${error.message}`)
  codeEmail = email
  codeHint.textContent = `${t.codeSent} ${email}.`
  form.hidden = true
  codeForm.hidden = false
})

codeForm.addEventListener('submit', async (ev) => {
  ev.preventDefault()
  const token = String(new FormData(codeForm).get('token') ?? '').trim()
  const { error } = await supabase.auth.verifyOtp({ email: codeEmail, token, type: 'email' })
  if (error) fail(t.codeWrong)
})

$<HTMLButtonElement>('#signout').addEventListener('click', () => void supabase.auth.signOut())

function renderSignedIn(email: string | null): void {
  signedIn = !!email
  // A running demo owns the screen until it is stopped.
  gate.hidden = !!email || !!demo
  deck.hidden = !email
  $('#who').textContent = email ? `${t.connectedAs} ${email}` : ''
  if (!email) {
    providers.hidden = !!glasses
    form.hidden = !glasses
    codeForm.hidden = true
    void stopListening()
  }
}

for (const b of demoBtns) b.addEventListener('click', () => toggleDemo())

async function boot(): Promise<void> {
  glasses = await GlassesRenderer.connect()
  glasses?.onInput(onInput)
  glasses?.setMenuLabels({ start: t.menuStart, stop: t.menuStop, ask: t.menuAsk, demo: t.menuDemo })
  if (glasses) {
    // Before anything else: the glasses mic is refused until a page exists,
    // and `startListening` opens the mic well before the first frame is due.
    await glasses.ensurePage(stage.frame())
    log('Even bridge connected — the glasses will mirror this screen')

    // Opening the app from the glasses' own menu is the one hands-free
    // signal we get — the phone was never touched. If a session is already
    // signed in (a prior one-time-code sign-in persisted its token), start
    // listening immediately instead of waiting for a ring tap or a menu
    // click; if not signed in, startListening()'s own "Signed out." path
    // handles it and the glasses just show no active session.
    glasses.onLaunchSource((source) => {
      if (source !== 'glassesMenu' || session) return
      void supabase.auth.getSession().then(({ data }) => {
        if (data.session && !session) void startListening()
      })
    })
  }

  if (glasses) {
    // Inside the Even app the one-time code is the only way in.
    $('#in-app-hint').hidden = false
    providers.hidden = true
    form.hidden = false
    form.querySelector<HTMLInputElement>('input[name=password]')!.required = false
  }

  // Back from an OAuth redirect: the session is stored, so tidy the URL.
  if (/[?&](code|access_token|error)=/.test(location.search + location.hash)) {
    history.replaceState(null, '', returnUrl())
  }

  const { data: { session: s } } = await supabase.auth.getSession()
  renderSignedIn(s?.user.email ?? null)
  supabase.auth.onAuthStateChange((_e, next) => renderSignedIn(next?.user.email ?? null))
}

void boot()

// Dev-only hook, matching the live page's: lets Playwright drive the Stage
// without a microphone or an account. Tree-shaken out of production.
if (import.meta.env.DEV) {
  ;(window as unknown as { __tp: unknown }).__tp = {
    signedIn: (email: string | null) => renderSignedIn(email),
    state: (s: Parameters<Stage['onState']>[0]) => stage.onState(s),
    steer: (s: Parameters<Stage['onSteer']>[0]) => stage.onSteer(s),
    cue: (c: Parameters<Stage['onCue']>[0]) => stage.onCue(c),
    log,
  }
}
